COINS = (25, 10, 5, 1)


def fewest(cents):
    """Fewest coins for `cents`, computed the slow but obvious way."""
    best = [0] + [None] * cents
    for amount in range(1, cents + 1):
        for value in COINS:
            if value <= amount and best[amount - value] is not None:
                candidate = best[amount - value] + 1
                if best[amount] is None or candidate < best[amount]:
                    best[amount] = candidate
    return best[cents]


